import React, { useEffect, useState } from 'react';
import { getServerData } from '../helper/helper';

export default function ResultTable() {
    const [data, setData] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        getServerData(`/api/result`, (res) => {
            setData(res);
            setLoading(false);
        }).catch((error) => {
            console.error('Error fetching result data:', error);
            setLoading(false);
        });
    }, []);

    if (loading) return <p className="text-light" style={{ textAlign: 'center' }}>Loading scoreboard...</p>;
    if (!data || data.length === 0) return <p className="text-light" style={{ textAlign: 'center' }}>No results yet.</p>;

    return (
        <div>
            <table>
                <thead className="table-header">
                    <tr>
                        <td>#</td>
                        <td>Name</td>
                        <td>Attempts</td>
                        <td>Points Earned</td>
                        <td>Result</td>
                    </tr>
                </thead>
                <tbody>
                    {data.map((v, i) => (
                        <tr className="table-body" key={i}>
                            <td>{i + 1}</td>
                            <td>{v?.username || ''}</td>
                            <td>{v?.attempts || 0}</td>
                            <td>{v?.points || 0}</td>
                            <td
                                style={{
                                    color: v?.achived === 'Passed' ? '#2aff95' : '#ff2a66',
                                    fontWeight: 'bold',
                                }}
                            >
                                {v?.achived || ''}
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
}
